messages.body_plain:
I am trying to create an dynamic app which has the following functionality:
1) Allow user to select x and Y variable.
2) All the X variables selected will be displayed in Main Panel and corresponding to each variable , we will have different transformations (Adstock, log etc).
3) These transformations will be then be applied to that variable and will be used henceforth.

Issue : When I add new variable to data table, my previous values of transformations to variables already present in data table gets reset.

Requirement: When the variable is present in data table, user can change selections of transformations corresponding to that variable any number of times. The last updated selections should be used for that variable. Also, when a new variable is added to Data table, variables already present in Data table should not get affected.

Here is my code

UI.R

library(shiny)
shinyUI(fluidPage(
  titlePanel(title='Modelling'),
  sidebarLayout(
    sidebarPanel(
      uiOutput("vary"),uiOutput("varx")
    ),
    mainPanel(
      DT::dataTableOutput('mod')

    )
  )
))

Server.R

shinyServer(function(input,output,session)({

  shinyInput = function(FUN, len, id, ...) {
    inputs = character(len)
    for (i in seq_len(len)) {
      inputs[i] = as.character(FUN(id, label = NULL, ...))
    }
    inputs
  }
  data <- mtcars

  output$vary <- renderUI({
    selectInput("variabley", "select the Y variable", choices=names(data),multiple = F)
  })

  output$varx <- renderUI({
    x <- setdiff(names(data),input$variabley)
    checkboxGroupInput("variablex", "select the X variable", choices=x)
  })

 df <- data.frame()

  dat <- eventReactive(input$variablex,{
    if(is.null(input$variablex)){
      return()
    }
    else {
      for(i in 1:length(input$variablex)){

        v$hist_value_ad <- input[[paste("id_n_", input$variablex[i], sep="")]]
        v$hist_value_ad <- ifelse (!is.null(v$hist_value_ad),v$hist_value_ad,1)
        v$hist_value_log <- input[[paste("id_c_", input$variablex[i], sep="")]]
        v$hist_value_log <- ifelse (!is.null(v$hist_value_log),v$hist_value_log,F)

        #print(hist_value_ad)
        #print(hist_value_log)
      yy <- data.frame(
           value = input$variablex[i],
           adstock = shinyInput(numericInput,1, paste("id_n_", input$variablex[i], sep=""), value = v$hist_value_ad,min=1,max=10,step=0.5,width=70),
           log = shinyInput(checkboxInput, 1, paste("id_c_", input$variablex[i], sep=""), value = v$hist_value_log),
           stringsAsFactors = FALSE
      )

      df <- rbind(isolate(df),yy)
      #print(hist_value_ad)
      }
    return(df)
    }
})
  output$mod = DT::renderDataTable(
    dat(), server = FALSE, escape = FALSE, selection = 'none', options = list(
      preDrawCallback = JS('function() { Shiny.unbindAll(this.api().table().node()); }'),
      drawCallback = JS('function() { Shiny.bindAll(this.api().table().node()); } '),
      autoWidth = TRUE)

  )
}))
